import Link from 'next/link';
import { getBooks } from '../lib/books';
import { addBookAction, markFinishedAction } from './actions';

export const dynamic = 'force-dynamic';

function BookList({ books, emptyText, showFinishButton }) {
  if (books.length === 0) {
    return <p className="empty">{emptyText}</p>;
  }
  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id}>
          <Link href={`/books/${book.id}`} className="book-link">
            <strong>{book.title}</strong> <span className="author">by {book.author}</span>
          </Link>
          {showFinishButton && (
            <form action={markFinishedAction}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit">Mark finished</button>
            </form>
          )}
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  return (
    <>
      <section>
        <h2>Currently reading</h2>
        <BookList books={reading} emptyText="Nothing on the go right now." showFinishButton />
      </section>

      <section>
        <h2>Finished</h2>
        <BookList books={finished} emptyText="No finished books yet." />
      </section>

      <section>
        <h2>Add a book</h2>
        <form action={addBookAction} className="add-form">
          <label>
            Title
            <input name="title" required />
          </label>
          <label>
            Author
            <input name="author" required />
          </label>
          <label>
            Notes
            <textarea name="notes" rows={4} />
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    </>
  );
}

