import Link from 'next/link';
import { notFound } from 'next/navigation';
import { getBook } from '../../../lib/books';
import { markFinishedAction } from '../../actions';

export const dynamic = 'force-dynamic';

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <article>
      <p>
        <Link href="/">&larr; All books</Link>
      </p>
      <h2>{book.title}</h2>
      <p className="author">by {book.author}</p>
      <p className="status">
        {book.status === 'finished' ? 'Finished' : 'Currently reading'}
      </p>

      {book.status === 'reading' && (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      )}

      <h3>Notes</h3>
      {book.notes ? <p className="notes">{book.notes}</p> : <p className="empty">No notes yet.</p>}
    </article>
  );
}

