* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  color: #1f2430;
  background: #fafaf7;
  margin: 0;
  line-height: 1.5;
}

.site-header {
  border-bottom: 1px solid #e3e1da;
  padding: 1rem 1.5rem;
}

.site-header a {
  font-weight: 700;
  font-size: 1.15rem;
  color: inherit;
  text-decoration: none;
}

main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1.5rem;
}

h2 {
  margin: 1.5rem 0 0.5rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.book-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.6rem 0;
  border-bottom: 1px solid #ecebe5;
}

.book-link {
  color: inherit;
  text-decoration: none;
}

.book-link:hover strong {
  text-decoration: underline;
}

.author {
  color: #6b7080;
}

.status {
  font-size: 0.9rem;
  color: #6b7080;
}

.empty {
  color: #9096a3;
  font-style: italic;
}

.notes {
  white-space: pre-wrap;
}

.add-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-width: 26rem;
}

.add-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-weight: 600;
  font-size: 0.9rem;
}

input,
textarea {
  font: inherit;
  padding: 0.45rem 0.6rem;
  border: 1px solid #c9c7bf;
  border-radius: 6px;
  background: #fff;
}

button {
  font: inherit;
  font-weight: 600;
  padding: 0.4rem 0.9rem;
  border: none;
  border-radius: 6px;
  background: #2f5d50;
  color: #fff;
  cursor: pointer;
  align-self: flex-start;
  white-space: nowrap;
}

button:hover {
  background: #254a40;
}

